import * as React from "react";

import { Calendar } from "@/registry/erbium/ui/calendar";
import { Card } from "@/registry/erbium/ui/card";

const year = new Date().getFullYear();

// Fifteen nights from January 12 are already booked.
const bookedDates = Array.from({ length: 15 }, (_, i) => new Date(year, 0, 12 + i));

export const CalendarBookedDates = () => {
  const [date, setDate] = React.useState<Date | undefined>(() => new Date(year, 0, 6));

  return (
    <Card className="mx-auto w-fit p-0">
      <Calendar
        mode="single"
        defaultMonth={date}
        selected={date}
        onSelect={setDate}
        disabled={bookedDates}
      />
    </Card>
  );
};

import { CalendarBookedDates } from "../examples/calendar-booked-dates";

const Example = () => <CalendarBookedDates />;

export default Example;
